package com.jinloes.practice;
import java.util.Arrays;
import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: a sorted integer array, then k=<count> and target=<value>, for example: [1, 2, 3, 4, 5] k=4 target=3"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) {runInput(String.join(" ",args).trim());return;} assertThat(Solution.closestValues(new int[]{1,2,3,4,5},4,3)).as("Example 1").containsExactly(1,2,3,4); assertThat(Solution.closestValues(new int[]{1,3,6,10},2,7)).as("Example 2").containsExactly(6,10); System.out.println("Examples passed: 2"); } private static void runInput(String input) {try{int kp=input.lastIndexOf("k="), tp=input.lastIndexOf("target="); if(kp<0||tp<kp)throw new IllegalArgumentException(); int[] a=parseArray(input.substring(0,kp).trim()); int k=Integer.parseInt(input.substring(kp+2,tp).trim()); int target=Integer.parseInt(input.substring(tp+7).trim()); System.out.println(Arrays.toString(Solution.closestValues(a,k,target)));}catch(RuntimeException e){System.out.println("Could not read \""+input+"\". "+USAGE);}} private static int[] parseArray(String text){String s=text.trim();if(!s.startsWith("[")||!s.endsWith("]"))throw new IllegalArgumentException("array");String b=s.substring(1,s.length()-1).trim();if(b.isEmpty())return new int[0];String[] parts=b.split(",");int[] a=new int[parts.length];for(int i=0;i<parts.length;i++)a[i]=Integer.parseInt(parts[i].trim());return a;} }


